    91→            var posX = (int)((rectangle.X + Util.Constants.LeftOffset) * scale);
    92→            var posY = (int)((rectangle.Y + Util.Constants.TopOffset) * scale);
    93→            var width = (int)((rectangle.Width - Util.Constants.HorizontalOffset) * scale);
    94→            var height = (int)((rectangle.Height - Util.Constants.VerticalOffset) * scale);
    95→
    96→            var hDesk = User32.GetDesktopWindow();
    97→            var hSrce = User32.GetWindowDC(hDesk);
    98→            var hDest = Gdi32.CreateCompatibleDC(hSrce);
    99→            var hBmp = Gdi32.CreateCompatibleBitmap(hSrce, width, height);
   100→            var hOldBmp = Gdi32.SelectObject(hDest, hBmp);
   101→
   102→            var b = Gdi32.BitBlt(hDest, 0, 0, width, height, hSrce, posX, posY, CopyPixelOperations.SourceCopy | CopyPixelOperations.CaptureBlt);
   103→
   104→            try
   105→            {
   106→                return Image.FromHbitmap(hBmp);
