   123→        public static System.Drawing.Bitmap CaptureImageCursor(ref System.Windows.Point point, double scale)
   124→        {
   125→            try
   126→            {
   127→                var cursorInfo = new CursorInfo();
   128→                cursorInfo.cbSize = Marshal.SizeOf(cursorInfo);
   129→
   130→                if (!User32.GetCursorInfo(out cursorInfo))
   131→                    return null;
   132→
   133→                if (cursorInfo.flags != Constants.CursorShowing)
   134→                    return null;
   135→
   136→                var hicon = User32.CopyIcon(cursorInfo.hCursor);
   137→                if (hicon == IntPtr.Zero)
   138→                    return null;
   139→
   140→                if (!User32.GetIconInfo(hicon, out var iconInfo))
   141→                {
   142→                    Gdi32.DeleteObject(hicon);
   143→                    return null;
   144→                }
   145→
   146→                point.X = cursorInfo.ptScreenPos.X - iconInfo.xHotspot;
   147→                point.Y = cursorInfo.ptScreenPos.Y - iconInfo.yHotspot;
   148→
   149→                using (var maskBitmap = Image.FromHbitmap(iconInfo.hbmMask))
   150→                {
   151→                    //Is this a monochrome cursor?  
   152→                    if (maskBitmap.Height == maskBitmap.Width * 2 && iconInfo.hbmColor == IntPtr.Zero)
   153→                    {
   154→                        var final = new System.Drawing.Bitmap(maskBitmap.Width, maskBitmap.Width);
   155→                        var hDesktop = User32.GetDesktopWindow();
   156→                        var dcDesktop = User32.GetWindowDC(hDesktop);
   157→
   158→                        using (var resultGraphics = Graphics.FromImage(final))
   159→                        {
   160→                            var resultHdc = resultGraphics.GetHdc();
   161→                            var offsetX = (int)((point.X + 3) * scale);
   162→                            var offsetY = (int)((point.Y + 3) * scale);
   163→
   164→                            Gdi32.BitBlt(resultHdc, 0, 0, final.Width, final.Height, dcDesktop, offsetX, offsetY, CopyPixelOperations.SourceCopy);
   165→                            User32.DrawIconEx(resultHdc, 0, 0, cursorInfo.hCursor, 0, 0, 0, IntPtr.Zero, 0x0003);
   166→
   167→                            //TODO: I have to try removing the background of this cursor capture.
   168→                            //Gdi32.BitBlt(resultHdc, 0, 0, final.Width, final.Height, dcDesktop, (int)point.X + 3, (int)point.Y + 3, CopyPixelOperations.SourceErase);
   169→
   170→                            //Original, ignores the screen as background.
   171→                            //Gdi32.BitBlt(resultHdc, 0, 0, resultBitmap.Width, resultBitmap.Height, maskHdc, 0, resultBitmap.Height, CopyPixelOperations.SourceCopy); //SourceCopy
   172→                            //Gdi32.BitBlt(resultHdc, 0, 0, resultBitmap.Width, resultBitmap.Height, maskHdc, 0, 0, CopyPixelOperations.PatInvert); //SourceInvert
   173→
   174→                            resultGraphics.ReleaseHdc(resultHdc);
   175→                            User32.ReleaseDC(hDesktop, dcDesktop);
   176→                        }
   177→
   178→                        Gdi32.DeleteObject(iconInfo.hbmMask);
   179→                        Gdi32.DeleteDC(dcDesktop);
   180→
   181→                        return final;
   182→                    }
   183→
   184→                    Gdi32.DeleteObject(iconInfo.hbmColor);
   185→                    Gdi32.DeleteObject(iconInfo.hbmMask);
   186→                    Gdi32.DeleteObject(hicon);
   187→                }
   188→
   189→                var icon = Icon.FromHandle(hicon);
   190→                return icon.ToBitmap();
   191→            }
   192→            catch (Exception ex)
   193→            {
   194→                LogWriter.Log(ex, "Impossible to get the cursor.");
   195→            }
   196→
   197→            return null;
   198→        }
   199→    }
