   267→    public override int Capture(FrameInfo frame)
   268→    {
   269→        var res = new Result(-1);
   270→
   271→        try
   272→        {
   273→            //Try to get the duplicated output frame within given time.
   274→            res = DuplicatedOutput.TryAcquireNextFrame(0, out var info, out var resource);
   275→
   276→            if (FrameCount == 0 && (res.Failure || resource == null))
   277→            {
   278→                //Somehow, it was not possible to retrieve the resource, frame or metadata.
   279→                resource?.Dispose();
   280→                return FrameCount;
   281→            }
   282→
   283→            #region Process changes
   284→
   285→            //Something on screen was moved or changed.
   286→            if (info.TotalMetadataBufferSize > 0)
   287→            {
   288→                //Copy resource into memory that can be accessed by the CPU.
   289→                using (var screenTexture = resource.QueryInterface<Texture2D>())
   290→                {
   291→                    #region Moved rectangles
   292→
   293→                    var movedRectangles = new OutputDuplicateMoveRectangle[info.TotalMetadataBufferSize];
   294→                    DuplicatedOutput.GetFrameMoveRects(movedRectangles.Length, movedRectangles, out var movedRegionsLength);
   295→
   296→                    for (var movedIndex = 0; movedIndex < movedRegionsLength / Marshal.SizeOf(typeof(OutputDuplicateMoveRectangle)); movedIndex++)
   297→                    {
   298→                        //Crop the destination rectangle to the screen area rectangle.
   299→                        var left = Math.Max(movedRectangles[movedIndex].DestinationRect.Left, Left - OffsetLeft);
   300→                        var right = Math.Min(movedRectangles[movedIndex].DestinationRect.Right, Left + Width - OffsetLeft);
   301→                        var top = Math.Max(movedRectangles[movedIndex].DestinationRect.Top, Top - OffsetTop);
   302→                        var bottom = Math.Min(movedRectangles[movedIndex].DestinationRect.Bottom, Top + Height - OffsetTop);
   303→
   304→                        //Copies from the screen texture only the area which the user wants to capture.
   305→                        if (right > left && bottom > top)
   306→                        {
   307→                            //Limit the source rectangle to the available size within the destination rectangle.
   308→                            var sourceWidth = movedRectangles[movedIndex].SourcePoint.X + (right - left);
   309→                            var sourceHeight = movedRectangles[movedIndex].SourcePoint.Y + (bottom - top);
   310→
   311→                            Device.ImmediateContext.CopySubresourceRegion(screenTexture, 0,
   312→                                new ResourceRegion(movedRectangles[movedIndex].SourcePoint.X, movedRectangles[movedIndex].SourcePoint.Y, 0, sourceWidth, sourceHeight, 1),
   313→                                StagingTexture, 0, left - (Left - OffsetLeft), top - (Top - OffsetTop));
   314→                        }
   315→                    }
   316→
   317→                    #endregion
   318→
   319→                    #region Dirty rectangles
   320→
   321→                    var dirtyRectangles = new RawRectangle[info.TotalMetadataBufferSize];
   322→                    DuplicatedOutput.GetFrameDirtyRects(dirtyRectangles.Length, dirtyRectangles, out var dirtyRegionsLength);
   323→
   324→                    for (var dirtyIndex = 0; dirtyIndex < dirtyRegionsLength / Marshal.SizeOf(typeof(RawRectangle)); dirtyIndex++)
   325→                    {
   326→                        //Crop screen positions and size to frame sizes.
   327→                        var left = Math.Max(dirtyRectangles[dirtyIndex].Left, Left - OffsetLeft);
   328→                        var right = Math.Min(dirtyRectangles[dirtyIndex].Right, Left + Width - OffsetLeft);
   329→                        var top = Math.Max(dirtyRectangles[dirtyIndex].Top, Top - OffsetTop);
   330→                        var bottom = Math.Min(dirtyRectangles[dirtyIndex].Bottom, Top + Height - OffsetTop);
   331→
   332→                        //Copies from the screen texture only the area which the user wants to capture.
   333→                        if (right > left && bottom > top)
   334→                            Device.ImmediateContext.CopySubresourceRegion(screenTexture, 0, new ResourceRegion(left, top, 0, right, bottom, 1), StagingTexture, 0, left - (Left - OffsetLeft), top - (Top - OffsetTop));
   335→                    }
   336→
   337→                    #endregion
   338→                }
   339→            }
   340→
   341→            #endregion
   342→
   343→            #region Gets the image data
   344→
   345→            //Gets the staging texture as a stream.
   346→            var data = Device.ImmediateContext.MapSubresource(StagingTexture, 0, MapMode.Read, MapFlags.None);
   347→
   348→            if (data.IsEmpty)
   349→            {
   350→                Device.ImmediateContext.UnmapSubresource(StagingTexture, 0);
   351→                resource?.Dispose();
   352→                return FrameCount;
   353→            }
   354→
   355→            var bitmap = new System.Drawing.Bitmap(Width, Height, PixelFormat.Format32bppArgb);
   356→            var boundsRect = new System.Drawing.Rectangle(0, 0, Width, Height);
   357→
   358→            //Copy pixels from screen capture Texture to the GDI bitmap.
   359→            var mapDest = bitmap.LockBits(boundsRect, ImageLockMode.WriteOnly, bitmap.PixelFormat);
   360→            var sourcePtr = data.DataPointer;
   361→            var destPtr = mapDest.Scan0;
   362→
   363→            for (var y = 0; y < Height; y++)
   364→            {
   365→                //Copy a single line.
   366→                Utilities.CopyMemory(destPtr, sourcePtr, Width * 4);
   367→
   368→                //Advance pointers.
   369→                sourcePtr = IntPtr.Add(sourcePtr, data.RowPitch);
   370→                destPtr = IntPtr.Add(destPtr, mapDest.Stride);
   371→            }
   372→
   373→            //Release source and dest locks.
   374→            bitmap.UnlockBits(mapDest);
   375→
   376→            //Set frame details.
   377→            FrameCount++;
   378→            frame.Path = $"{Project.FullPath}{FrameCount}.png";
   379→            frame.Delay = FrameRate.GetMilliseconds();
   380→            frame.Image = bitmap;
   381→
   382→            if (IsAcceptingFrames)
   383→                BlockingCollection.Add(frame);
   384→
   385→            #endregion
   386→
   387→            Device.ImmediateContext.UnmapSubresource(StagingTexture, 0);
   388→
   389→            resource?.Dispose();
   390→            return FrameCount;
   391→        }
   392→        catch (SharpDXException se) when (se.ResultCode.Code == SharpDX.DXGI.ResultCode.WaitTimeout.Result.Code)
   393→        {
   394→            return FrameCount;
   395→        }
   396→        catch (SharpDXException se) when (se.ResultCode.Code == SharpDX.DXGI.ResultCode.DeviceRemoved.Result.Code || se.ResultCode.Code == SharpDX.DXGI.ResultCode.DeviceReset.Result.Code)
   397→        {
   398→            //When the device gets lost or reset, the resources should be instantiated again.
   399→            DisposeInternal();
   400→            Initialize();
   401→
   402→            return FrameCount;
   403→        }
   404→        catch (Exception ex)
   405→        {
   406→            LogWriter.Log(ex, "It was not possible to finish capturing the frame with DirectX.");
   407→
   408→            MajorCrashHappened = true;
   409→
   410→            if (IsAcceptingFrames)
   411→                Application.Current.Dispatcher.Invoke(() => OnError.Invoke(ex));
   412→
   413→            return FrameCount;
   414→        }
   415→        finally
   416→        {
   417→            try
   418→            {
   419→                //Only release the frame if there was a success in capturing it.
   420→                if (res.Success)
   421→                    DuplicatedOutput.ReleaseFrame();
   422→            }
   423→            catch (Exception e)
   424→            {
   425→                LogWriter.Log(e, "It was not possible to release the frame.");
   426→            }
   427→        }
   428→    }
