   435→    public override int CaptureWithCursor(FrameInfo frame)
   436→    {
   437→        var res = new Result(-1);
   438→
   439→        try
   440→        {
   441→            //Try to get the duplicated output frame within given time.
   442→            res = DuplicatedOutput.TryAcquireNextFrame(0, out var info, out var resource);
   443→
   444→            //Checks how to proceed with the capture. It could have failed, or the screen, cursor or both could have been captured.
   445→            if (FrameCount == 0 && info.LastMouseUpdateTime == 0 && (res.Failure || resource == null))
   446→            {
   447→                //Somehow, it was not possible to retrieve the resource, frame or metadata.
   448→                resource?.Dispose();
   449→                return FrameCount;
   450→            }
   451→            else if (FrameCount == 0 && info.TotalMetadataBufferSize == 0 && info.LastMouseUpdateTime > 0)
   452→            {
   453→                //Sometimes, the first frame has cursor info, but no screen changes.
   454→                GetCursor(null, info, frame);
   455→                resource?.Dispose();
   456→                return FrameCount;
   457→            }
   458→
   459→            #region Process changes
   460→
   461→            //Something on screen was moved or changed.
   462→            if (info.TotalMetadataBufferSize > 0)
   463→            {
   464→                //Copies the screen data into memory that can be accessed by the CPU.
   465→                using (var screenTexture = resource.QueryInterface<Texture2D>())
   466→                {
   467→                    #region Moved rectangles
   468→
   469→                    var movedRectangles = new OutputDuplicateMoveRectangle[info.TotalMetadataBufferSize];
   470→                    DuplicatedOutput.GetFrameMoveRects(movedRectangles.Length, movedRectangles, out var movedRegionsLength);
   471→
   472→                    for (var movedIndex = 0; movedIndex < movedRegionsLength / Marshal.SizeOf(typeof(OutputDuplicateMoveRectangle)); movedIndex++)
   473→                    {
   474→                        //Crop the destination rectangle to the screen area rectangle.
   475→                        var left = Math.Max(movedRectangles[movedIndex].DestinationRect.Left, Left - OffsetLeft);
   476→                        var right = Math.Min(movedRectangles[movedIndex].DestinationRect.Right, Left + Width - OffsetLeft);
   477→                        var top = Math.Max(movedRectangles[movedIndex].DestinationRect.Top, Top - OffsetTop);
   478→                        var bottom = Math.Min(movedRectangles[movedIndex].DestinationRect.Bottom, Top + Height - OffsetTop);
   479→
   480→                        //Copies from the screen texture only the area which the user wants to capture.
   481→                        if (right > left && bottom > top)
   482→                        {
   483→                            //Limit the source rectangle to the available size within the destination rectangle.
   484→                            var sourceWidth = movedRectangles[movedIndex].SourcePoint.X + (right - left);
   485→                            var sourceHeight = movedRectangles[movedIndex].SourcePoint.Y + (bottom - top);
   486→
   487→                            Device.ImmediateContext.CopySubresourceRegion(screenTexture, 0,
   488→                                new ResourceRegion(movedRectangles[movedIndex].SourcePoint.X, movedRectangles[movedIndex].SourcePoint.Y, 0, sourceWidth, sourceHeight, 1),
   489→                                BackingTexture, 0, left - (Left - OffsetLeft), top - (Top - OffsetTop));
   490→                        }
   491→                    }
   492→
   493→                    #endregion
   494→
   495→                    #region Dirty rectangles
   496→
   497→                    var dirtyRectangles = new RawRectangle[info.TotalMetadataBufferSize];
   498→                    DuplicatedOutput.GetFrameDirtyRects(dirtyRectangles.Length, dirtyRectangles, out var dirtyRegionsLength);
   499→
   500→                    for (var dirtyIndex = 0; dirtyIndex < dirtyRegionsLength / Marshal.SizeOf(typeof(RawRectangle)); dirtyIndex++)
   501→                    {
   502→                        //Crop screen positions and size to frame sizes.
   503→                        var left = Math.Max(dirtyRectangles[dirtyIndex].Left, Left - OffsetLeft);
   504→                        var right = Math.Min(dirtyRectangles[dirtyIndex].Right, Left + Width - OffsetLeft);
   505→                        var top = Math.Max(dirtyRectangles[dirtyIndex].Top, Top - OffsetTop);
   506→                        var bottom = Math.Min(dirtyRectangles[dirtyIndex].Bottom, Top + Height - OffsetTop);
   507→
   508→                        //Copies from the screen texture only the area which the user wants to capture.
   509→                        if (right > left && bottom > top)
   510→                            Device.ImmediateContext.CopySubresourceRegion(screenTexture, 0, new ResourceRegion(left, top, 0, right, bottom, 1), BackingTexture, 0, left - (Left - OffsetLeft), top - (Top - OffsetTop));
   511→                    }
   512→
   513→                    #endregion
   514→                }
   515→            }
   516→
   517→            if (info.TotalMetadataBufferSize > 0 || info.LastMouseUpdateTime > 0)
   518→            {
   519→                //Copy the captured desktop texture into a staging texture, in order to show the mouse cursor and not make the captured texture dirty with it.
   520→                Device.ImmediateContext.CopyResource(BackingTexture, StagingTexture);
   521→
   522→                //Gets the cursor image and merges with the staging texture.
   523→                GetCursor(StagingTexture, info, frame);
   524→            }
   525→
   526→            //Saves the most recent capture time.
   527→            LastProcessTime = Math.Max(info.LastPresentTime, info.LastMouseUpdateTime);
   528→
   529→            #endregion
   530→
   531→            #region Gets the image data
   532→
   533→            //Get the desktop capture texture.
   534→            var data = Device.ImmediateContext.MapSubresource(StagingTexture, 0, MapMode.Read, MapFlags.None);
   535→
   536→            if (data.IsEmpty)
   537→            {
   538→                Device.ImmediateContext.UnmapSubresource(StagingTexture, 0);
   539→                resource?.Dispose();
   540→                return FrameCount;
   541→            }
   542→
   543→            var bitmap = new System.Drawing.Bitmap(Width, Height, PixelFormat.Format32bppArgb);
   544→            var boundsRect = new System.Drawing.Rectangle(0, 0, Width, Height);
   545→
   546→            //Copy pixels from screen capture Texture to the GDI bitmap.
   547→            var mapDest = bitmap.LockBits(boundsRect, ImageLockMode.WriteOnly, bitmap.PixelFormat);
   548→            var sourcePtr = data.DataPointer;
   549→            var destPtr = mapDest.Scan0;
   550→
   551→            for (var y = 0; y < Height; y++)
   552→            {
   553→                //Copy a single line.
   554→                Utilities.CopyMemory(destPtr, sourcePtr, Width * 4);
   555→
   556→                //Advance pointers.
   557→                sourcePtr = IntPtr.Add(sourcePtr, data.RowPitch);
   558→                destPtr = IntPtr.Add(destPtr, mapDest.Stride);
   559→            }
   560→
   561→            //Releases the source and dest locks.
   562→            bitmap.UnlockBits(mapDest);
   563→
   564→            //Set frame details.
   565→            FrameCount++;
   566→            frame.Path = $"{Project.FullPath}{FrameCount}.png";
   567→            frame.Delay = FrameRate.GetMilliseconds();
   568→            frame.Image = bitmap;
   569→
   570→            if (IsAcceptingFrames)
   571→                BlockingCollection.Add(frame);
   572→
   573→            #endregion
   574→
   575→            Device.ImmediateContext?.UnmapSubresource(StagingTexture, 0);
   576→
   577→            resource?.Dispose();
   578→            return FrameCount;
   579→        }
   580→        catch (SharpDXException se) when (se.ResultCode.Code == SharpDX.DXGI.ResultCode.WaitTimeout.Result.Code)
   581→        {
   582→            return FrameCount;
   583→        }
   584→        catch (SharpDXException se) when (se.ResultCode.Code == SharpDX.DXGI.ResultCode.DeviceRemoved.Result.Code || se.ResultCode.Code == SharpDX.DXGI.ResultCode.DeviceReset.Result.Code)
   585→        {
   586→            //When the device gets lost or reset, the resources should be instantiated again.
   587→            DisposeInternal();
   588→            Initialize();
   589→
   590→            return FrameCount;
   591→        }
   592→        catch (Exception ex)
   593→        {
   594→            LogWriter.Log(ex, "It was not possible to finish capturing the frame with DirectX.");
   595→
   596→            MajorCrashHappened = true;
   597→
   598→            if (IsAcceptingFrames)
   599→                Application.Current.Dispatcher.Invoke(() => OnError.Invoke(ex));
   600→
   601→            return FrameCount;
   602→        }
   603→        finally
   604→        {
   605→            try
   606→            {
   607→                //Only release the frame if there was a success in capturing it.
   608→                if (res.Success)
   609→                    DuplicatedOutput.ReleaseFrame();
   610→            }
   611→            catch (Exception e)
   612→            {
   613→                LogWriter.Log(e, "It was not possible to release the frame.");
   614→            }
   615→        }
   616→    }
