   766→    protected internal bool GetCursor(Texture2D screenTexture, OutputDuplicateFrameInformation info, FrameInfo frame)
   767→    {
   768→        //Prepare buffer array to hold the cursor shape.
   769→        if (CursorShapeBuffer == null || info.PointerShapeBufferSize > CursorShapeBuffer.Length)
   770→            CursorShapeBuffer = new byte[info.PointerShapeBufferSize];
   771→
   772→        //If there's a cursor shape available to be captured.
   773→        if (info.PointerShapeBufferSize > 0)
   774→        {
   775→            //Pin the buffer in order to pass the address as parameter later.
   776→            var pinnedBuffer = GCHandle.Alloc(CursorShapeBuffer, GCHandleType.Pinned);
   777→            var cursorBufferAddress = pinnedBuffer.AddrOfPinnedObject();
   778→
   779→            //Load the cursor shape into the buffer.
   780→            DuplicatedOutput.GetFramePointerShape(info.PointerShapeBufferSize, cursorBufferAddress, out _, out CursorShapeInfo);
   781→
   782→            //If the cursor is monochrome, it will return the cursor shape twice, one is the mask.
   783→            if (CursorShapeInfo.Type == 1)
   784→                CursorShapeInfo.Height /= 2;
   785→
   786→            //The buffer must be unpinned, to free resources.
   787→            pinnedBuffer.Free();
   788→        }
   789→
   790→        //Store the current cursor position, if it was moved.
   791→        if (info.LastMouseUpdateTime != 0)
   792→            PreviousPosition = info.PointerPosition;
   793→
   794→        //TODO: In a future version, don't merge the cursor image in here, let the editor do that.
   795→        //Saves the position of the cursor, so the editor can add the mouse events overlay later.
   796→        frame.CursorX = PreviousPosition.Position.X - (Left - OffsetLeft);
   797→        frame.CursorY = PreviousPosition.Position.Y - (Top - OffsetTop);
   798→
   799→        //If the method is supposed to simply the get the cursor shape no shape was loaded before, there's nothing else to do.
   800→        //if (CursorShapeBuffer?.Length == 0 || (info.LastPresentTime == 0 && info.LastMouseUpdateTime == 0) || !info.PointerPosition.Visible)
   801→        if (screenTexture == null || CursorShapeBuffer?.Length == 0)// || !info.PointerPosition.Visible)
   802→        {
   803→            //FallbackCursorCapture(frame);
   804→
   805→            //if (CursorShapeBuffer != null)
   806→            return false;
   807→        }
   808→
   809→        //Don't let it bleed beyond the top-left corner, calculate the dimensions of the portion of the cursor that will appear.
   810→        var leftCut = frame.CursorX;
   811→        var topCut = frame.CursorY;
   812→        var rightCut = screenTexture.Description.Width - (frame.CursorX + CursorShapeInfo.Width);
   813→        var bottomCut = screenTexture.Description.Height - (frame.CursorY + CursorShapeInfo.Height);
   814→
   815→        //Adjust to the hotspot offset, so it's possible to add the highlight correctly later.
   816→        frame.CursorX += CursorShapeInfo.HotSpot.X;
   817→        frame.CursorY += CursorShapeInfo.HotSpot.Y;
   818→
   819→        //Don't try merging the textures if the cursor is out of bounds.
   820→        if (leftCut + CursorShapeInfo.Width < 1 || topCut + CursorShapeInfo.Height < 1 || rightCut + CursorShapeInfo.Width < 1 || bottomCut + CursorShapeInfo.Height < 1)
   821→            return false;
   822→
   823→        var cursorLeft = Math.Max(leftCut, 0);
   824→        var cursorTop = Math.Max(topCut, 0);
   825→        var cursorWidth = leftCut < 0 ? CursorShapeInfo.Width + leftCut : rightCut < 0 ? CursorShapeInfo.Width + rightCut : CursorShapeInfo.Width;
   826→        var cursorHeight = topCut < 0 ? CursorShapeInfo.Height + topCut : bottomCut < 0 ? CursorShapeInfo.Height + bottomCut : CursorShapeInfo.Height;
   827→
   828→        //The staging texture must be able to hold all pixels.
   829→        if (CursorStagingTexture == null || CursorStagingTexture.Description.Width != cursorWidth || CursorStagingTexture.Description.Height != cursorHeight)
   830→        {
   831→            //In order to change the size of the texture, I need to instantiate it again with the new size.
   832→            CursorStagingTexture?.Dispose();
   833→            CursorStagingTexture = new Texture2D(Device, new Texture2DDescription
   834→            {
   835→                ArraySize = 1,
   836→                BindFlags = BindFlags.None,
   837→                CpuAccessFlags = CpuAccessFlags.Write,
   838→                Height = cursorHeight,
   839→                Format = Format.B8G8R8A8_UNorm,
   840→                Width = cursorWidth,
   841→                MipLevels = 1,
   842→                OptionFlags = ResourceOptionFlags.None,
   843→                SampleDescription = new SampleDescription(1, 0),
   844→                Usage = ResourceUsage.Staging
   845→            });
   846→        }
   847→
   848→        //The region where the cursor is located is copied to the staging texture to act as the background when dealing with masks and transparency.
   849→        //The cutout must be the exact region needed and it can't overflow. It's not allowed to try to cut outside of the screenTexture region.
   850→        var region = new ResourceRegion
   851→        {
   852→            Left = cursorLeft,
   853→            Top = cursorTop,
   854→            Front = 0,
   855→            Right = cursorLeft + cursorWidth,
   856→            Bottom = cursorTop + cursorHeight,
   857→            Back = 1
   858→        };
   859→
   860→        //Copy from the screen the region in which the cursor is located.
   861→        Device.ImmediateContext.CopySubresourceRegion(screenTexture, 0, region, CursorStagingTexture, 0);
   862→
   863→        //Get cursor details and draw it to the staging texture.
   864→        DrawCursorShape(CursorStagingTexture, CursorShapeInfo, CursorShapeBuffer, leftCut < 0 ? leftCut * -1 : 0, topCut < 0 ? topCut * -1 : 0, cursorWidth, cursorHeight);
   865→
   866→        //Copy back the cursor texture to the screen texture.
   867→        Device.ImmediateContext.CopySubresourceRegion(CursorStagingTexture, 0, null, screenTexture, 0, cursorLeft, cursorTop);
   868→
   869→        return true;
   870→    }
