   872→    private void DrawCursorShape(Texture2D texture, OutputDuplicatePointerShapeInformation info, byte[] buffer, int leftCut, int topCut, int cursorWidth, int cursorHeight)
   873→    {
   874→        using (var surface = texture.QueryInterface<Surface>())
   875→        {
   876→            //Maps the surface, indicating that the CPU needs access to the data.
   877→            var rect = surface.Map(SharpDX.DXGI.MapFlags.Write);
   878→
   879→            //Cursors can be divided into 3 types:
   880→            switch (info.Type)
   881→            {
   882→                //Masked monochrome, a cursor which reacts with the background.
   883→                case (int)OutputDuplicatePointerShapeType.Monochrome:
   884→                    DrawMonochromeCursor(leftCut, topCut, cursorWidth, cursorHeight, rect, info.Pitch, buffer, info.Height);
   885→                    break;
   886→
   887→                //Color, a colored cursor which supports transparency.
   888→                case (int)OutputDuplicatePointerShapeType.Color:
   889→                    DrawColorCursor(leftCut, topCut, cursorWidth, cursorHeight, rect, info.Pitch, buffer);
   890→                    break;
   891→
   892→                //Masked color, a mix of both previous types.
   893→                case (int)OutputDuplicatePointerShapeType.MaskedColor:
   894→                    DrawMaskedColorCursor(leftCut, topCut, cursorWidth, cursorHeight, rect, info.Pitch, buffer);
   895→                    break;
   896→            }
   897→
   898→            surface.Unmap();
   899→        }
   900→    }
   901→
   902→    private void DrawMonochromeCursor(int offsetX, int offsetY, int width, int height, DataRectangle rect, int pitch, byte[] buffer, int actualHeight)
   903→    {
   904→        for (var row = offsetY; row < height; row++)
   905→        {
   906→            //128 in binary.
   907→            byte mask = 0x80;
   908→
   909→            //Simulate the offset, adjusting the mask.
   910→            for (var off = 0; off < offsetX; off++)
   911→            {
   912→                if (mask == 0x01)
   913→                    mask = 0x80;
   914→                else
   915→                    mask = (byte)(mask >> 1);
   916→            }
   917→
   918→            for (var col = offsetX; col < width; col++)
   919→            {
   920→                var pos = (row - offsetY) * rect.Pitch + (col - offsetX) * 4;
   921→                var and = (buffer[row * pitch + col / 8] & mask) == mask; //Mask is take from the first half of the cursor image.
   922→                var xor = (buffer[row * pitch + col / 8 + actualHeight * pitch] & mask) == mask; //Mask is taken from the second half of the cursor image, hence the "+ height * pitch".
   923→
   924→                //Reads current pixel and applies AND and XOR. (AND/XOR ? White : Black)
   925→                Marshal.WriteByte(rect.DataPointer, pos, (byte)((Marshal.ReadByte(rect.DataPointer, pos) & (and ? 255 : 0)) ^ (xor ? 255 : 0)));
   926→                Marshal.WriteByte(rect.DataPointer, pos + 1, (byte)((Marshal.ReadByte(rect.DataPointer, pos + 1) & (and ? 255 : 0)) ^ (xor ? 255 : 0)));
   927→                Marshal.WriteByte(rect.DataPointer, pos + 2, (byte)((Marshal.ReadByte(rect.DataPointer, pos + 2) & (and ? 255 : 0)) ^ (xor ? 255 : 0)));
   928→                Marshal.WriteByte(rect.DataPointer, pos + 3, (byte)((Marshal.ReadByte(rect.DataPointer, pos + 3) & 255) ^ 0));
   929→
   930→                //Shifts the mask around until it reaches 1, then resets it back to 128.
   931→                if (mask == 0x01)
   932→                    mask = 0x80;
   933→                else
   934→                    mask = (byte)(mask >> 1);
   935→            }
   936→        }
   937→    }
   938→
   939→    private void DrawColorCursor(int offsetX, int offsetY, int width, int height, DataRectangle rect, int pitch, byte[] buffer)
   940→    {
   941→        for (var row = offsetY; row < height; row++)
   942→        {
   943→            for (var col = offsetX; col < width; col++)
   944→            {
   945→                var surfaceIndex = (row - offsetY) * rect.Pitch + (col - offsetX) * 4;
   946→                var bufferIndex = row * pitch + col * 4;
   947→                var alpha = buffer[bufferIndex + 3] + 1;
   948→
   949→                if (alpha == 1)
   950→                    continue;
   951→
   952→                //Premultiplied alpha values.
   953→                var invAlpha = 256 - alpha;
   954→                alpha += 1;
   955→
   956→                Marshal.WriteByte(rect.DataPointer, surfaceIndex, (byte)((alpha * buffer[bufferIndex] + invAlpha * Marshal.ReadByte(rect.DataPointer, surfaceIndex)) >> 8));
   957→                Marshal.WriteByte(rect.DataPointer, surfaceIndex + 1, (byte)((alpha * buffer[bufferIndex + 1] + invAlpha * Marshal.ReadByte(rect.DataPointer, surfaceIndex + 1)) >> 8));
   958→                Marshal.WriteByte(rect.DataPointer, surfaceIndex + 2, (byte)((alpha * buffer[bufferIndex + 2] + invAlpha * Marshal.ReadByte(rect.DataPointer, surfaceIndex + 2)) >> 8));
   959→            }
   960→        }
   961→    }
   962→
   963→    private void DrawMaskedColorCursor(int offsetX, int offsetY, int width, int height, DataRectangle rect, int pitch, byte[] buffer)
   964→    {
   965→        //ImageUtil.ImageMethods.SavePixelArrayToFile(buffer, width, height, 4, System.IO.Path.GetFullPath(".\\MaskedColor.png"));
   966→
   967→        for (var row = offsetY; row < height; row++)
   968→        {
   969→            for (var col = offsetX; col < width; col++)
   970→            {
