     1→using System;
     2→using System.Drawing.Imaging;
     3→using System.Runtime.InteropServices;
     4→using ScreenToGif.Model;
     5→using ScreenToGif.Util;
     6→using SharpDX;
     7→using SharpDX.Direct3D11;
     8→using SharpDX.DXGI;
     9→using SharpDX.Mathematics.Interop;
    10→using MapFlags = SharpDX.Direct3D11.MapFlags;
    11→
    12→namespace ScreenToGif.Capture;
    13→
    14→internal class DirectChangedImageCapture : DirectImageCapture
    15→{
    16→    public override int Capture(FrameInfo frame)
    17→    {
    18→        var res = new Result(-1);
    19→        var wasCaptured = false;
    20→
    21→        try
    22→        {
    23→            //Try to get the duplicated output frame within given time.
    24→            res = DuplicatedOutput.TryAcquireNextFrame(0, out var info, out var resource);
    25→
    26→            if (res.Failure || resource == null || info.TotalMetadataBufferSize == 0)
    27→            {
    28→                //Somehow, it was not possible to retrieve the resource, frame or metadata.
    29→                resource?.Dispose();
    30→                return FrameCount;
    31→            }
    32→
    33→            #region Process changes
    34→
    35→            //Copy resource into memory that can be accessed by the CPU.
    36→            using (var screenTexture = resource.QueryInterface<Texture2D>())
    37→            {
    38→                #region Moved rectangles
    39→
    40→                var movedRectangles = new OutputDuplicateMoveRectangle[info.TotalMetadataBufferSize];
    41→                DuplicatedOutput.GetFrameMoveRects(movedRectangles.Length, movedRectangles, out var movedRegionsLength);
    42→
    43→                for (var movedIndex = 0; movedIndex < movedRegionsLength / Marshal.SizeOf(typeof(OutputDuplicateMoveRectangle)); movedIndex++)
    44→                {
    45→                    //Crop the destination rectangle to the scree area rectangle.
    46→                    var left = Math.Max(movedRectangles[movedIndex].DestinationRect.Left, Left);
    47→                    var right = Math.Min(movedRectangles[movedIndex].DestinationRect.Right, Left + Width);
    48→                    var top = Math.Max(movedRectangles[movedIndex].DestinationRect.Top, Top);
    49→                    var bottom = Math.Min(movedRectangles[movedIndex].DestinationRect.Bottom, Top + Height);
    50→
    51→                    //Copies from the screen texture only the area which the user wants to capture.
    52→                    if (right > left && bottom > top)
    53→                    {
    54→                        //Limit the source rectangle to the available size within the destination rectangle.
    55→                        var sourceWidth = movedRectangles[movedIndex].SourcePoint.X + (right - left);
    56→                        var sourceHeight = movedRectangles[movedIndex].SourcePoint.Y + (bottom - top);
    57→
    58→                        Device.ImmediateContext.CopySubresourceRegion(screenTexture, 0, new ResourceRegion(movedRectangles[movedIndex].SourcePoint.X, movedRectangles[movedIndex].SourcePoint.Y, 0, sourceWidth, sourceHeight, 1),
    59→                            StagingTexture, 0, left - Left, top - Top);
    60→                        wasCaptured = true;
    61→                    }
    62→                }
    63→
    64→                #endregion
    65→
    66→                #region Dirty rectangles
    67→
    68→                var dirtyRectangles = new RawRectangle[info.TotalMetadataBufferSize];
    69→                DuplicatedOutput.GetFrameDirtyRects(dirtyRectangles.Length, dirtyRectangles, out var dirtyRegionsLength);
    70→
    71→                for (var dirtyIndex = 0; dirtyIndex < dirtyRegionsLength / Marshal.SizeOf(typeof(RawRectangle)); dirtyIndex++)
    72→                {
    73→                    //Crop screen positions and size to frame sizes.
    74→                    var left = Math.Max(dirtyRectangles[dirtyIndex].Left, Left);
    75→                    var right = Math.Min(dirtyRectangles[dirtyIndex].Right, Left + Width);
    76→                    var top = Math.Max(dirtyRectangles[dirtyIndex].Top, Top);
    77→                    var bottom = Math.Min(dirtyRectangles[dirtyIndex].Bottom, Top + Height);
    78→
    79→                    //Copies from the screen texture only the area which the user wants to capture.
    80→                    if (right > left && bottom > top)
    81→                    {
    82→                        Device.ImmediateContext.CopySubresourceRegion(screenTexture, 0, new ResourceRegion(left, top, 0, right, bottom, 1), StagingTexture, 0, left - Left, top - Top);
    83→                        wasCaptured = true;
    84→                    }
    85→                }
    86→
    87→                #endregion
    88→
    89→                if (!wasCaptured)
    90→                {
    91→                    //Nothing was changed within the capture region, so ignore this frame.
    92→                    resource.Dispose();
    93→                    return FrameCount;
    94→                }
    95→            }
    96→
    97→            #endregion
    98→
    99→            #region Gets the image data
   100→
   101→            //Gets the staging texture as a stream.
   102→            var data = Device.ImmediateContext.MapSubresource(StagingTexture, 0, MapMode.Read, MapFlags.None);
   103→
   104→            if (data.IsEmpty)
   105→            {
   106→                Device.ImmediateContext.UnmapSubresource(StagingTexture, 0);
   107→                resource?.Dispose();
   108→                return FrameCount;
   109→            }
   110→
   111→            var bitmap = new System.Drawing.Bitmap(Width, Height, PixelFormat.Format32bppArgb);
   112→            var boundsRect = new System.Drawing.Rectangle(0, 0, Width, Height);
   113→
   114→            //Copy pixels from screen capture Texture to the GDI bitmap.
   115→            var mapDest = bitmap.LockBits(boundsRect, ImageLockMode.WriteOnly, bitmap.PixelFormat);
   116→            var sourcePtr = data.DataPointer;
   117→            var destPtr = mapDest.Scan0;
   118→
   119→            for (var y = 0; y < Height; y++)
   120→            {
   121→                //Copy a single line.
   122→                Utilities.CopyMemory(destPtr, sourcePtr, Width * 4);
   123→
   124→                //Advance pointers.
   125→                sourcePtr = IntPtr.Add(sourcePtr, data.RowPitch);
   126→                destPtr = IntPtr.Add(destPtr, mapDest.Stride);
   127→            }
   128→
   129→            //Release source and dest locks.
   130→            bitmap.UnlockBits(mapDest);
   131→
   132→            //Set frame details.
   133→            FrameCount++;
   134→            frame.Path = $"{Project.FullPath}{FrameCount}.png";
   135→            frame.Delay = FrameRate.GetMilliseconds();
   136→            frame.Image = bitmap;
   137→            BlockingCollection.Add(frame);
   138→
   139→            #endregion
   140→
   141→            Device.ImmediateContext.UnmapSubresource(StagingTexture, 0);
   142→
   143→            resource?.Dispose();
   144→            return FrameCount;
   145→        }
   146→        catch (SharpDXException se) when (se.ResultCode.Code == SharpDX.DXGI.ResultCode.WaitTimeout.Result.Code)
   147→        {
   148→            return FrameCount;
   149→        }
   150→        catch (SharpDXException se) when (se.ResultCode.Code == SharpDX.DXGI.ResultCode.DeviceRemoved.Result.Code || se.ResultCode.Code == SharpDX.DXGI.ResultCode.DeviceReset.Result.Code)
   151→        {
   152→            //When the device gets lost or reset, the resources should be instantiated again.
   153→            DisposeInternal();
   154→            Initialize();
   155→
   156→            return FrameCount;
   157→        }
   158→        catch (Exception ex)
   159→        {
   160→            LogWriter.Log(ex, "It was not possible to finish capturing the frame with DirectX.");
   161→
   162→            OnError.Invoke(ex);
   163→            return FrameCount;
   164→        }
   165→        finally
   166→        {
   167→            try
   168→            {
   169→                //Only release the frame if there was a success in capturing it.
   170→                if (res.Success)
   171→                    DuplicatedOutput.ReleaseFrame();
   172→            }
   173→            catch (Exception e)
   174→            {
   175→                LogWriter.Log(e, "It was not possible to release the frame.");
   176→            }
   177→        }
   178→    }
   179→
   180→    public override int CaptureWithCursor(FrameInfo frame)
   181→    {
   182→        var res = new Result(-1);
   183→        var wasCaptured = false;
   184→
   185→        try
   186→        {
   187→            //Try to get the duplicated output frame within given time.
   188→            res = DuplicatedOutput.TryAcquireNextFrame(0, out var info, out var resource);
